/* @lc app=leetcode id=3598 lang=kotlin */ class Solution { fun lc(a: String, b: String): Int = a.commonPrefixWith(b).length fun longestCommonPrefix(words: Array<String>): IntArray = words.size.let { n -> (0 until n - 1).map { lc(words[it], words[it + 1]) }.let { lcp -> lcp.runningFold(0) { a, b -> maxOf(a, b) }.let { pre -> lcp.reversed().runningFold(0) { a, b -> maxOf(a, b) }.reversed().let { suf -> IntArray(n) { i -> maxOf(if (i >= 1) pre[i - 1] else 0, if (i + 1 <= n - 1) suf[i + 1] else 0, if (i >= 1 && i <= n - 2) lc(words[i - 1], words[i + 1]) else 0) } } } } } }